import { timestamp, uuid } from 'drizzle-orm/pg-core';

// Shared column builders. Spread or call these in every table so ids and
// audit timestamps look the same across the whole schema.

// Primary key: random UUID generated by Postgres.
export const primaryId = () => uuid('id').primaryKey().defaultRandom();

// created_at / updated_at. updated_at is refreshed by Drizzle on every update.
export const timestamps = {
    createdAt: timestamp('created_at', { withTimezone: true })
        .defaultNow()
        .notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
        .defaultNow()
        .notNull()
        .$onUpdate(() => new Date()),
};
